33: public class ErrorHandler implements Handler<ErroredHttpServerRequest> {
34: 
35:   private final Logger logger = LoggerFactory.getLogger(getClass());
36: 
37:   private final TemplateRenderer templateRenderer;
38: 
39:   @Inject
40:   public ErrorHandler(TemplateRenderer templateRenderer) {
41:     this.templateRenderer = templateRenderer;
42:   }
43: 
44:   @Override
45:   public void handle(ErroredHttpServerRequest erroredRequest) {
46:     erroredRequest.getRequest().resume();
47:     @SuppressWarnings("ThrowableResultOfMethodCallIgnored")
48:     Exception error = (Exception) StackTraceUtils.deepSanitize(erroredRequest.getException());
49:     logger.error("error handling " + erroredRequest.getRequest().uri, error);
50:     HttpServerRequest request = erroredRequest.getRequest();
51:     request.response.statusCode = 500;
52:     renderException(error, request, new FallbackErrorHandlingTemplateRenderer(request, "rendering error template"));
53:   }
54: 
55:   public <T> AsyncResultHandler<T> asyncHandler(final HttpServerRequest request, final Handler<T> handler) {
56:     return new AsyncResultHandler<T>() {
57:       @Override
58:       public void handle(AsyncResult<T> event) {
59:         if (event.failed()) {
60:           ErrorHandler.this.handle(new ErroredHttpServerRequest(request, event.exception));
61:         } else {
62:           handler(request, handler).handle(event.result);
63:         }
64:       }
65:     };
66:   }
67: 
68:   public <T> Handler<T> handler(final HttpServerRequest request, final Handler<T> handler) {
69:     return new Handler<T>() {
70:       @Override
71:       public void handle(T event) {
72:         try {
73:           handler.handle(event);
74:         } catch (Exception exception) {
75:           ErrorHandler.this.handle(new ErroredHttpServerRequest(request, exception));
76:         }
77:       }
78:     };
79:   }
80: 
81:   void renderException(Exception exception, HttpServerRequest request, AsyncResultHandler<Buffer> handler) {
82:     DecodedStackTrace stackTrace = decodeStackTrace(exception);
83:     Map<String, Object> model = new LinkedHashMap<String, Object>();
84:     model.put("title", exception.getClass().getName());
85:     model.put("message", exception.getMessage());
86:     model.put("stacktrace", stackTrace.html);
87: 
88:     Map<String, Object> metadata = new LinkedHashMap<String, Object>();
89:     metadata.put("Request Method", request.method.toUpperCase());
90:     metadata.put("Request URL", request.uri);
91:     metadata.put("Exception Type", exception.getClass().getName());
92:     metadata.put("Exception Location", stackTrace.rootCause.getFileName() + ", line " + stackTrace.rootCause.getLineNumber());
93:     model.put("metadata", metadata);
94: 
95:     templateRenderer.renderError(model, handler);
96:   }
97: 
98:   private static class DecodedStackTrace {
99:     final String html;
100:     final StackTraceElement rootCause;
101: 
102:     DecodedStackTrace(String html, StackTraceElement rootCause) {
103:       this.html = html;
104:       this.rootCause = rootCause;
105:     }
106:   }
107: 
108:   protected static DecodedStackTrace decodeStackTrace(Exception exception) {
109:     StringBuilder html = new StringBuilder();
110:     html.append(exception.toString()).append("\n");
111:     StackTraceElement rootCause = null;
112: 
113:     for (StackTraceElement ste : exception.getStackTrace()) {
114:       if (!StackTraceUtils.isApplicationClass(ste.getClassName())) {
115:         html.append("<span class='stack-thirdparty'>        at ").append(ste.toString()).append("</span>\n");
116:       } else {
117:         html.append("        at ").append(ste.toString()).append("\n");
118:         if (rootCause == null) {
119:           rootCause = ste;
120:         }
121:       }
122:     }
123: 
124:     return new DecodedStackTrace(html.toString(), rootCause);
125:   }
