108:   private static void extractProperties(String propertyPrefix, Properties properties, Map<? super String, ? super String> destination) {
109:     for (String propertyName : properties.stringPropertyNames()) {
110:       if (propertyName.startsWith(propertyPrefix)) {
111:         destination.put(propertyName.substring(propertyPrefix.length()), properties.getProperty(propertyName));
112:       }
113:     }
114:   }
