116:   /**
117:    * Delegates to {@link #createFromFile(ClassLoader, java.io.File, java.io.File, java.util.Properties, java.util.Properties)}, after trying to find the config properties file.
118:    * <p>
119:    * The {@code overrideProperties} are queried for the {@link #CONFIG_RESOURCE_PROPERTY} (defaulting to {@link #CONFIG_RESOURCE_DEFAULT}).
120:    * The {@code classLoader} is asked for the classpath resource with this name.
121:    * <p>
122:    * If the resource DOES NOT exist, {@link #createFromFile(ClassLoader, java.io.File, java.io.File, java.util.Properties, java.util.Properties)} is called with
123:    * the current JVM user dir as the {@code baseDir} and {@code null} as the {@code configFile}.
124:    * <p>
125:    * If the resource DOES exist, {@link #createFromFile(ClassLoader, java.io.File, java.io.File, java.util.Properties, java.util.Properties)} is called with
126:    * that file resource as the {@code configFile}, and its parent directory as the {@code baseDir}.
127:    *
128:    * @param classLoader The classloader to use to find the properties file
129:    * @param overrideProperties The properties that provide the path to the config file resource, and any overrides
130:    * @param defaultProperties The default properties to use when a property is omitted
131:    * @return A launch config
132:    */
133:   public static LaunchConfig createFromProperties(ClassLoader classLoader, Properties overrideProperties, Properties defaultProperties) {
134:     String configResourceValue = overrideProperties.getProperty(CONFIG_RESOURCE_PROPERTY, CONFIG_RESOURCE_DEFAULT);
135:     File configFile = new File(CONFIG_RESOURCE_DEFAULT);
136:     if (!configFile.exists()) {
137:       URL configResourceUrl = classLoader.getResource(configResourceValue);
